\set ON_ERROR_STOP on
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000003',false);
select public.catalog_test_error(format('select public.ai_catalog_document_unlink(%L,%L)',r.value->>'id',d.value->>'id'),'FORBIDDEN','reader cannot remove file from a record') from public.catalog_test_state r,public.catalog_test_state d where r.name='team' and d.name='doc';
select public.catalog_test_error(format('select public.ai_catalog_document_archive(%L)',d.value->>'id'),'FORBIDDEN','reader cannot archive shared file') from public.catalog_test_state d where d.name='doc';
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
select public.catalog_test_assert(public.ai_catalog_document_link((r.value->>'id')::uuid,(d.value->>'id')::uuid),'shared file can be linked to another record') from public.catalog_test_state r,public.catalog_test_state d where r.name='caseB' and d.name='doc';
reset role;
update ai_management.records set archived_at=now() where id=(select (value->>'id')::uuid from public.catalog_test_state where name='caseB');
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
select public.catalog_test_error(format('select public.ai_catalog_document_archive(%L)',d.value->>'id'),'FORBIDDEN','file linked to a record in Trash cannot be archived') from public.catalog_test_state d where d.name='doc';
reset role;
update ai_management.records set archived_at=null where id=(select (value->>'id')::uuid from public.catalog_test_state where name='caseB');
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
select public.catalog_test_assert(public.ai_catalog_document_unlink((r.value->>'id')::uuid,(d.value->>'id')::uuid),'editor can remove linked file') from public.catalog_test_state r,public.catalog_test_state d where r.name='team' and d.name='doc';
select public.catalog_test_assert(not exists(select 1 from jsonb_array_elements(public.ai_catalog_get((r.value->>'id')::uuid)->'documents') item where item->>'id'=d.value->>'id'),'removed file disappears only from its folder') from public.catalog_test_state r,public.catalog_test_state d where r.name='team' and d.name='doc';
select public.catalog_test_assert(exists(select 1 from jsonb_array_elements(public.ai_catalog_get((r.value->>'id')::uuid)->'documents') item where item->>'id'=d.value->>'id'),'unlink preserves the file in another record') from public.catalog_test_state r,public.catalog_test_state d where r.name='caseB' and d.name='doc';
select public.catalog_test_assert(exists(select 1 from jsonb_array_elements(public.ai_catalog_documents()) item where item->>'id'=d.value->>'id'),'unlinked file remains available in shared library') from public.catalog_test_state d where d.name='doc';
select public.catalog_test_assert(public.ai_catalog_document_archive((d.value->>'id')::uuid),'creator can archive file') from public.catalog_test_state d where d.name='doc';
select public.catalog_test_assert(not exists(select 1 from jsonb_array_elements(public.ai_catalog_documents()) item where item->>'id'=d.value->>'id'),'archived file disappears from library') from public.catalog_test_state d where d.name='doc';
select public.catalog_test_assert(not exists(select 1 from jsonb_array_elements(public.ai_catalog_get((r.value->>'id')::uuid)->'documents') item where item->>'id'=d.value->>'id'),'archived file disappears from all linked records') from public.catalog_test_state r,public.catalog_test_state d where r.name='caseB' and d.name='doc';
select public.catalog_test_error('select public.ai_catalog_download(''20000000-0000-4000-8000-000000000002'')','NOT_FOUND','archived file cannot be downloaded');
reset role;
reset request.jwt.claim.sub;
update ai_management.records set archived_at=now() where id=(select (value->>'id')::uuid from public.catalog_test_state where name='caseB');
set role authenticated;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000002',false);
select public.catalog_test_error(format('select public.ai_catalog_document_unlink(%L,%L)',r.value->>'id',d.value->>'id'),'FORBIDDEN','file links in Trash cannot be removed') from public.catalog_test_state r,public.catalog_test_state d where r.name='caseB' and d.name='doc';
reset role;
reset request.jwt.claim.sub;
select public.catalog_test_assert((select count(*) from ai_management.document_versions where document_id=(select (value->>'id')::uuid from public.catalog_test_state where name='doc'))=2,'archival retains source version rows for audit');
